    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        (bool success, bytes memory retdata) = address(c).call(abi.encodeWithSelector(Owned.setOwner.selector, newOwner));
        require(success, "call failed");
        bool returned = abi.decode(retdata, (bool));
        assertTrue(returned);
